/// `CDecoObjMgr` plant kinds, SettlerValues.xml `other` (CDefineTranslator).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u16)]
pub enum DecoKind {
    VINE = 0,
    AGAVE = 1,
    TREE = 2,
    GRAIN = 3,
    HIVE = 6,
    MUSHROOM = 4,
    SUNFLOWER = 7,
}
impl DecoKind {
    pub const ALL: &'static [DecoKind] = &[DecoKind::VINE, DecoKind::AGAVE, DecoKind::TREE, DecoKind::GRAIN, DecoKind::HIVE, DecoKind::MUSHROOM, DecoKind::SUNFLOWER];
    /// The define name used in the game data (XML files, scripts).
    pub fn name(self) -> &'static str {
        match self {
            DecoKind::VINE => "CDecoObjMgr::VINE",
            DecoKind::AGAVE => "CDecoObjMgr::AGAVE",
            DecoKind::TREE => "CDecoObjMgr::TREE",
            DecoKind::GRAIN => "CDecoObjMgr::GRAIN",
            DecoKind::HIVE => "CDecoObjMgr::HIVE",
            DecoKind::MUSHROOM => "CDecoObjMgr::MUSHROOM",
            DecoKind::SUNFLOWER => "CDecoObjMgr::SUNFLOWER",
        }
    }
    pub fn from_name(s: &str) -> Option<Self> {
        match s {
            "CDecoObjMgr::VINE" => Some(DecoKind::VINE),
            "CDecoObjMgr::AGAVE" => Some(DecoKind::AGAVE),
            "CDecoObjMgr::TREE" => Some(DecoKind::TREE),
            "CDecoObjMgr::GRAIN" => Some(DecoKind::GRAIN),
            "CDecoObjMgr::HIVE" => Some(DecoKind::HIVE),
            "CDecoObjMgr::MUSHROOM" => Some(DecoKind::MUSHROOM),
            "CDecoObjMgr::SUNFLOWER" => Some(DecoKind::SUNFLOWER),
            _ => None,
        }
    }
    pub fn from_u16(v: u16) -> Option<Self> {
        match v {
            0 => Some(DecoKind::VINE),
            1 => Some(DecoKind::AGAVE),
            2 => Some(DecoKind::TREE),
            3 => Some(DecoKind::GRAIN),
            6 => Some(DecoKind::HIVE),
            4 => Some(DecoKind::MUSHROOM),
            7 => Some(DecoKind::SUNFLOWER),
            _ => None,
        }
    }
}

